{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.DOD_CLICK_SHARE_DASHBOARD AS WITH daily_widget AS ( SELECT TO_DATE(REQUEST_DATE) AS REQUEST_DATE, SOURCE, SOURCE_WIDGET, SUM(COALESCE(CLICKS, 0)) AS CLICKS, SUM(COALESCE(IMPRESSION, 0)) AS IMPRESSIONS, SUM(COALESCE(ADD_TO_CART, 0)) AS ADD_TO_CART, SUM(COALESCE(PAYMENT, 0)) AS PAYMENT, SUM(COALESCE(PURCHASE, 0)) AS PURCHASE FROM SNITCH_DB.MAPLEMONK.CLICKSTREAM_METABASE WHERE REQUEST_DATE IS NOT NULL AND ( UPPER(SKU_GROUP) LIKE \'4MBG%\' OR UPPER(SKU_GROUP) LIKE \'4B%\' ) GROUP BY TO_DATE(REQUEST_DATE), SOURCE, SOURCE_WIDGET ), with_totals AS ( SELECT *, SUM(CLICKS) OVER ( PARTITION BY REQUEST_DATE, SOURCE ) AS SOURCE_DAILY_CLICKS, SUM(CLICKS) OVER ( PARTITION BY REQUEST_DATE ) AS TOTAL_DAILY_CLICKS FROM daily_widget ), click_share AS ( SELECT *, 100.0 * CLICKS / NULLIF(SOURCE_DAILY_CLICKS, 0) AS SOURCE_CLICK_SHARE_PCT, 100.0 * CLICKS / NULLIF(TOTAL_DAILY_CLICKS, 0) AS OVERALL_CLICK_SHARE_PCT, 100.0 * CLICKS / NULLIF(IMPRESSIONS, 0) AS CTR_PCT, 100.0 * ADD_TO_CART / NULLIF(CLICKS, 0) AS CLICK_TO_ATC_PCT, 100.0 * PAYMENT / NULLIF(ADD_TO_CART, 0) AS ATC_TO_PAYMENT_PCT, 100.0 * PURCHASE / NULLIF(PAYMENT, 0) AS PAYMENT_TO_PURCHASE_PCT, 100.0 * PURCHASE / NULLIF(CLICKS, 0) AS CLICK_TO_PURCHASE_PCT FROM with_totals ), dod AS ( SELECT *, LAG(SOURCE_CLICK_SHARE_PCT) OVER ( PARTITION BY SOURCE, SOURCE_WIDGET ORDER BY REQUEST_DATE ) AS PREVIOUS_DAY_SOURCE_CLICK_SHARE_PCT, LAG(OVERALL_CLICK_SHARE_PCT) OVER ( PARTITION BY SOURCE, SOURCE_WIDGET ORDER BY REQUEST_DATE ) AS PREVIOUS_DAY_OVERALL_CLICK_SHARE_PCT, LAG(CLICKS) OVER ( PARTITION BY SOURCE, SOURCE_WIDGET ORDER BY REQUEST_DATE ) AS PREVIOUS_DAY_CLICKS FROM click_share ) SELECT REQUEST_DATE, SOURCE, SOURCE_WIDGET, CLICKS, IMPRESSIONS, ADD_TO_CART, PAYMENT, PURCHASE, SOURCE_DAILY_CLICKS, TOTAL_DAILY_CLICKS, SOURCE_CLICK_SHARE_PCT, PREVIOUS_DAY_SOURCE_CLICK_SHARE_PCT, SOURCE_CLICK_SHARE_PCT - PREVIOUS_DAY_SOURCE_CLICK_SHARE_PCT AS DOD_SOURCE_CLICK_SHARE_CHANGE_PP, OVERALL_CLICK_SHARE_PCT, PREVIOUS_DAY_OVERALL_CLICK_SHARE_PCT, OVERALL_CLICK_SHARE_PCT - PREVIOUS_DAY_OVERALL_CLICK_SHARE_PCT AS DOD_OVERALL_CLICK_SHARE_CHANGE_PP, CLICKS - PREVIOUS_DAY_CLICKS AS DOD_CLICKS_CHANGE, CTR_PCT, CLICK_TO_ATC_PCT, ATC_TO_PAYMENT_PCT, PAYMENT_TO_PURCHASE_PCT, CLICK_TO_PURCHASE_PCT FROM dod;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            